import json

最后错误 = {"文本": ""}

def 抛出结构化错误(码, 消息):
    最后错误["文本"] = json.dumps({"码": 码, "消息": 消息}, ensure_ascii=False)
    raise RuntimeError(最后错误["文本"])

def 解析错误消息(消息字符串):
    try:
        return json.loads(消息字符串)
    except Exception:
        return None

try:
    抛出结构化错误("拒绝", "未授权")
except Exception:
    print(解析错误消息(最后错误["文本"]))

